export const VERSION=1;
export const fresh=()=>({version:VERSION,map:'village',x:14,y:15,dir:'up',level:1,xp:0,gold:20,potions:5,hp:92,mp:26,edHp:78,ed:true,weapon:0,armor:0,ore:0,herbs:0,flags:{},defeated:[],collected:[],lore:[],valves:[],steps:0,played:0,chapter:0});
export const maxHp=s=>92+(s.level-1)*18;export const maxMp=s=>26+(s.level-1)*5;export const maxEd=s=>78+(s.level-1)*15;
export const levelNeed=s=>s.level*28;
export function reward(s,xp,gold){s.xp+=xp;s.gold+=gold;let levels=0;while(s.xp>=levelNeed(s)&&s.level<12){s.xp-=levelNeed(s);s.level++;levels++;s.hp=maxHp(s);s.mp=maxMp(s);s.edHp=maxEd(s);}return levels;}
export function heal(s){if(s.potions<1)return false;if(s.hp===maxHp(s)&&s.edHp===maxEd(s))return false;s.potions--;s.hp=Math.min(maxHp(s),s.hp+65);s.edHp=Math.min(maxEd(s),s.edHp+50);return true;}
export function rest(s){s.hp=maxHp(s);s.mp=maxMp(s);s.edHp=maxEd(s);}
export const enemies={wolf:{name:'霜牙の狼',hp:42,atk:12,xp:16,gold:12,kind:'wolf',intent:['bite','charge','heavy']},moth:{name:'霊光の蛾',hp:38,atk:10,xp:14,gold:10,kind:'moth',intent:['drain','charge','heavy']},crawler:{name:'坑道の石殻蟲',hp:61,atk:14,xp:22,gold:18,kind:'crawler',intent:['bite','guard','heavy']},sentinel:{name:'遺跡の自動守衛',hp:86,atk:17,xp:32,gold:25,kind:'sentinel',intent:['charge','heavy','guard','bite']},bear:{name:'過負荷の熊型機霊',hp:150,atk:19,xp:65,gold:60,kind:'bear',intent:['charge','heavy','drain','heavy'],boss:true}};
export function beginBattle(type,id){const e=enemies[type];return {...e,type,id,currentHp:e.hp,turn:0,focus:0,guard:false,stability:0,heard:false,log:[],result:null};}
export const intentName=b=>({bite:'次：通常攻撃',charge:'次：力をためる',heavy:'次：強攻撃！ 防御が有効',guard:'次：装甲を固める',drain:'次：霊流の乱れ'})[b.intent[b.turn%b.intent.length]];
export function battleTurn(s,b,action,rng=Math.random){if(b.result)return {result:b.result,lines:[]};let lines=[];let intent=b.intent[b.turn%b.intent.length];let damage=0;let guarding=false;const atk=13+s.level*3+s.weapon*6;const jitter=()=>Math.floor(rng()*4);
 if(action==='attack'){damage=atk+jitter();lines.push('ユリスの剣撃！');}
 else if(action==='skill'){if(s.mp<6)return {invalid:'集中力が足りない。防御で回復しよう。'};s.mp-=6;damage=Math.round(atk*1.85)+jitter();lines.push('ユリスは動きを見極め、踏み込んだ！');}
 else if(action==='listen'){if(b.boss){b.heard=true;b.stability+=1;lines.push('ノア「うん、私も聴きたい。手を添えて、マスター」','ユリスに声が届く。「止めるな……予備の導管へ……」');}else{b.focus=2;lines.push('ノアと息を合わせた。動きの隙が見える！ 次の2回の攻撃が強化。');}s.mp=Math.min(maxMp(s),s.mp+3);}
 else if(action==='guard'){guarding=true;s.mp=Math.min(maxMp(s),s.mp+5);lines.push('二人は身を守り、呼吸を整えた。集中力 +5');}
 else if(action==='potion'){if(!heal(s))return {invalid:s.potions<1?'薬草がない。':'体力は十分に回復している。'};lines.push('薬草を使った。ユリス +65 / エド +50 HP');}
 else if(action==='stabilize'){if(!b.boss||!b.heard)return {invalid:'まず「声を聴く」で機霊の願いを確かめよう。'};b.stability+=2;damage=18;lines.push('エドが予備弁を支え、ユリスが霊流を分散する。安定度 +2');}
 else if(action==='escape'){if(b.boss)return {invalid:'機霊を置いていくことはできない。'};b.result='escape';return {result:'escape',lines:['安全な場所まで退いた。']};}
 else return {invalid:'行動を選んでください。'};
 if(damage>0){if(b.focus>0){damage=Math.round(damage*1.5);b.focus--;lines.push('見極めた隙を捉えた！');}if(intent==='guard')damage=Math.round(damage*.55);if(b.boss&&action!=='stabilize'){damage=Math.round(damage*.55);lines.push('暴れる前脚を押し返す。機霊を傷つけずに抑える。');}b.currentHp=Math.max(0,b.currentHp-damage);lines.push(`${b.boss?'過負荷を':'相手のHPを'} ${damage} 減らした。`);}
 if(s.edHp>0&&['attack','skill'].includes(action)){const assist=5+s.level*2+s.weapon*2;b.currentHp=Math.max(0,b.currentHp-assist);lines.push(`エドが援護！ ${assist}`);}
 if(b.boss&&(b.stability>=7||(b.heard&&b.currentHp===0))){b.result='win';return {result:'win',lines:[...lines,'予備系統に霊流が戻る。機霊の苦しみが静まった。']};}
 if(!b.boss&&b.currentHp===0){b.result='win';return {result:'win',lines};}
 if(b.boss&&b.currentHp===0){b.currentHp=1;lines.push('力で抑えるだけでは救えない。「声を聴く」を使おう。');}
 if(intent==='charge')lines.push(`${b.name}は力をためている。次は強い攻撃が来る！`);
 else if(intent==='guard')lines.push(`${b.name}は身を固めている。`);
 else{let hit=Math.max(2,b.atk+jitter()-s.armor*3);if(intent==='heavy')hit=Math.round(hit*1.9);if(guarding)hit=Math.max(1,Math.round(hit*.28));s.hp=Math.max(0,s.hp-hit);if(s.edHp>0)s.edHp=Math.max(0,s.edHp-Math.round(hit*.55));if(intent==='drain')s.mp=Math.max(0,s.mp-2);lines.push(`${guarding?'防御で衝撃を受け流した。':'攻撃を受けた。'} ユリス −${hit} HP`);}
 b.turn++;if(s.hp===0){b.result='lose';return {result:'lose',lines:[...lines,'ノアとエドがユリスを安全な場所へ運んだ。']};}return {lines};}
export function validateSave(v){if(!v||v.version!==VERSION||!['village','forest','mine','ruins','heart'].includes(v.map))return null;let s=fresh();for(const k of ['x','y','level','xp','gold','potions','hp','mp','edHp','weapon','armor','ore','herbs','steps','played','chapter']){if(!Number.isFinite(v[k])||v[k]<0||v[k]>1e7)return null;s[k]=Math.floor(v[k]);}if(s.level<1||s.level>12||s.x>33||s.y>25||s.weapon>2||s.armor>2||s.chapter>4)return null;for(const k of ['defeated','collected','lore','valves']){if(!Array.isArray(v[k])||v[k].some(a=>typeof a!=='string')||v[k].length>200)return null;s[k]=v[k];}if(!v.flags||typeof v.flags!=='object'||Array.isArray(v.flags))return null;s.flags=Object.fromEntries(Object.entries(v.flags).filter(([k,val])=>/^[a-zA-Z0-9_]+$/.test(k)&&typeof val==='boolean'));s.map=v.map;s.dir=['up','down','left','right'].includes(v.dir)?v.dir:'down';s.hp=Math.min(maxHp(s),s.hp);s.mp=Math.min(maxMp(s),s.mp);s.edHp=Math.min(maxEd(s),s.edHp);return s;}
export function quest(s){if(s.flags.ending)return {title:'灯りの戻った町',text:'星灯りの坑道、完結。残った手帳や依頼を探して、ノルヴィクを歩こう。',items:[['機霊を救い、町に帰る',true]]};if(s.flags.bear)return {title:'この灯りを、みんなへ',text:'町へ帰り、広場のヴィクトルに報告しよう。',items:[['熊型機霊の霊流を整える',true],['ヴィクトルに報告',false]]};if(s.flags.gate)return {title:'大地の心臓',text:'最深部で苦しむ機霊を救おう。「声を聴く」が鍵になる。',items:[['三つの予備弁を開く',true],['機霊の願いを聴く',false]]};if(s.flags.pump)return {title:'眠れるものの声',text:'排水された坑道の北、古代遺跡へ。石碑を読み、予備弁を正しい順序で開こう。',items:[['坑道のポンプを修復',true],[`予備弁を開く ${s.valves.length}/3`,s.flags.gate]]};if(s.flags.quest)return {title:'止まったポンプ',text:'森と坑道で霊晶片を3つ集め、坑道入口のドーランへ届けよう。',items:[[ `霊晶片を集める ${s.ore}/3`,s.ore>=3],['ドーランとポンプを修復',false]]};return {title:'雪解けの声',text:'広場のヴィクトルに話しかけよう。ノアは地下から小さな震えを感じている。',items:[['広場で事情を聞く',false]]};}
